package za.ac.cput.controller; import org.springframework.web.bind.annotation.*; import za.ac.cput.domain.Manager; import za.ac.cput.service.ManagerService; import java.util.List; @RestController @RequestMapping("/manager") public class ManagerController{private final ManagerService service; public ManagerController(ManagerService service){this.service=service;} @PostMapping("/create") public Manager create(@RequestBody Manager x){return service.create(x);} @GetMapping("/read/{id}") public Manager read(@PathVariable String id){return service.read(id);} @PutMapping("/update") public Manager update(@RequestBody Manager x){return service.update(x);} @DeleteMapping("/delete/{id}") public boolean delete(@PathVariable String id){return service.delete(id);} @GetMapping("/getAll") public List<Manager> getAll(){return service.findAll();} }